def _df_from(fixture, code):
    n = len(fixture)
    return pl.DataFrame({
        "code": [code] * n,
        "date": [date.fromisoformat(r[0]) for r in fixture],
        "open": [r[1] for r in fixture],
        "high": [r[2] for r in fixture],
        "low": [r[3] for r in fixture],
        "close": [r[4] for r in fixture],
        "volume": [float(r[5]) for r in fixture],
    })


def _run_selector(df, market_cap):
    defn = make_bbi_kdj_b1_defn()
    sel = defn.selector_class(defn)
    warmup = sel.warmup(df)
    ctx = SelectionContext(
        trade_date=df["date"].max(),
        market_data=df,
        candidate_codes=df["code"].unique().to_list(),
        market_cap=market_cap,
    )
    return sorted(sel.select_day(ctx, warmup).selected_codes)


def _reference_hit(df):
    """朴素逐行实现：返回每只股票最后一天 XG 是否命中。"""
    def ema(seq, n):
        a = 2 / (n + 1); y = [seq[0]]
        for t in range(1, len(seq)):
            y.append(a * seq[t] + (1 - a) * y[-1])
        return y

    def ma(seq, n):
        return [sum(seq[max(0, i - n + 1):i + 1]) / len(seq[max(0, i - n + 1):i + 1]) for i in range(len(seq))]

    def llv(seq, n):
        return [min(seq[max(0, i - n + 1):i + 1]) for i in range(len(seq))]

    def hhv(seq, n):
        return [max(seq[max(0, i - n + 1):i + 1]) for i in range(len(seq))]

    def count(seq, n):
        return [sum(1 for x in seq[max(0, i - n + 1):i + 1] if x) for i in range(len(seq))]

    out = {}
    for g in df.partition_by("code"):
        code = g["code"][0]
        g = g.sort("date")
        cs, os_, hs, ls, vs = (g[c].to_list() for c in ("close", "open", "high", "low", "volume"))
        n = len(cs); i = n - 1
        prev_c = [None] + cs[:-1]; prev_v = [None] + vs[:-1]
        rsv = [(c - lv) / (hv - lv + 1e-10) * 100 for c, hv, lv in zip(cs, hhv(hs, 9), llv(ls, 9))]
        k = [rsv[0]]
        for t in range(1, n):
            k.append((rsv[t] + 2 * k[-1]) / 3)
        d = [k[0]]
        for t in range(1, n):
            d.append((k[t] + 2 * d[-1]) / 3)
        j = [3 * kk - 2 * dd for kk, dd in zip(k, d)]
        zf = (hs[i] - ls[i]) / prev_c[i] * 100
        zg = (cs[i] - prev_c[i]) / prev_c[i] * 100
        blz = [pv is not None and v > 2 * pv for v, pv in zip(vs, prev_v)]
        dq = ema(ema(cs, 10), 10)
        dk = [sum(m) / len(m) for m in zip(*[ma(cs, w) for w in (14, 28, 57, 114)])]
        out[code] = bool(
            j[i] < 13 and zf < 7 and zg < 2 and zg > -2 and cs[i] > ma(cs, 60)[i]
            and count(blz, 20)[i] >= 1 and dq[i] > dk[i] and cs[i] >= dk[i]
        )
    return out


def test_real_fixture_matches_reference():
    """真实行情：002322 公式命中、000001 不命中；selector 与参考一致。"""
    df = pl.concat([_df_from(_FIXTURE, "002322"), _df_from(_FIXTURE_MISS, "000001")])
    ref = _reference_hit(df)
    assert ref["002322"] is True, "真实样本 002322 应命中公式"
    assert ref["000001"] is False, "真实样本 000001 应不命中"
    assert _run_selector(df, {"002322": 600000.0, "000001": 600000.0}) == ["002322"]


def test_mvok_filters_below_50_yi():
    df = _df_from(_FIXTURE, "002322")
    assert _run_selector(df, {"002322": 499999.0}) == []
    assert _run_selector(df, {"002322": 500000.0}) == ["002322"]


